import click
from click.testing import CliRunner

# argument decorator reuse with extra attrs
class MyArg(click.Argument): pass
dec = click.argument("name", cls=MyArg, required=False)
@click.command()
@dec
def a(name): pass
@click.command()
@dec
def b(name): pass
print(type(a.params[0]).__name__, type(b.params[0]).__name__, a.params[0].required, b.params[0].required)

# option decorator reuse
class MyOpt(click.Option): pass
odec = click.option("--x", cls=MyOpt, help="hi")
@click.command()
@odec
def c(x): pass
@click.command()
@odec
def d(x): pass
print(type(c.params[0]).__name__, type(d.params[0]).__name__, c.params[0].help, d.params[0].help)

# multiple flag default
o = click.Option(["--flag"], is_flag=True, multiple=True)
print("multiple flag default:", o.default, o.flag_value)

# required flag with explicit default
@click.command()
@click.option("--f", is_flag=True, required=True, default=False)
def e(f): click.echo(f)
print("explicit default:", CliRunner().invoke(e, []).exit_code)
PYEOF
